  ('english_grammar', 11, 'intermediate', '"You had better see a doctor."를 부정형으로 바르게 바꾼 것은?', 'multiple_choice', '["You had better not see a doctor.","You hadn''t better see a doctor.","You had not better see a doctor.","You better not to see a doctor."]'::jsonb, 'You had better not see a doctor.', 'had better의 부정은 had better not입니다.'),
